window.VO = [{"text": "One hundred prisoners. One light bulb. Can they all walk free?", "cap": "100 prisoners \u00b7 1 light bulb", "dur": 3.388, "extra": 0.5, "file": "vo/00.wav"}, {"text": "Each prisoner is locked in a cell alone, and they can never talk to each other.", "cap": "No talking. Ever.", "dur": 3.883, "extra": 0.4, "file": "vo/01.wav"}, {"text": "Every day, the warden picks one prisoner at random, and takes them to a room with a single light bulb.", "cap": "1 random prisoner a day", "dur": 5.55, "extra": 0.6, "file": "vo/02.wav"}, {"text": "The bulb starts off. Inside, they can flip the switch, or leave it alone.", "cap": "Flip it, or leave it", "dur": 3.793, "extra": 0.6, "file": "vo/03.wav"}, {"text": "On any day, any prisoner can announce: all one hundred of us have been in that room.", "cap": "Anyone can announce", "dur": 4.102, "extra": 0.5, "file": "vo/04.wav"}, {"text": "If they're right, everyone goes free. If they're wrong, everyone stays locked up forever.", "cap": "Right = free. Wrong = forever.", "dur": 4.548, "extra": 0.6, "file": "vo/05.wav"}, {"text": "Before day one, they get one meeting to make a plan.", "cap": "1 meeting to plan", "dur": 2.718, "extra": 0.5, "file": "vo/06.wav"}, {"text": "What's your plan? Pause, and comment it below!", "cap": "Comment your plan!", "dur": 2.343, "extra": 9.2, "file": "vo/07.wav"}, {"text": "Here's a plan that works. They pick one prisoner to be the counter.", "cap": "Pick 1 counter", "dur": 3.454, "extra": 0.6, "file": "vo/08.wav"}, {"text": "Everyone else: the first time you find the bulb off, switch it on. Just once, ever.", "cap": "Everyone else: switch it ON once", "dur": 4.396, "extra": 0.6, "file": "vo/09.wav"}, {"text": "Only the counter switches it off. And each time, they add one mark to the wall.", "cap": "Counter: switch it OFF, +1 mark", "dur": 4.135, "extra": 0.6, "file": "vo/10.wav"}, {"text": "So a light that's on means: someone new has been here.", "cap": "ON = someone new was here", "dur": 2.525, "extra": 0.4, "file": "vo/11.wav"}, {"text": "Say on day two, prisoner twenty three finds it off, and switches it on.", "cap": "Day 2: #23 switches it on", "dur": 3.701, "extra": 0.5, "file": "vo/12.wav"}, {"text": "Day three, prisoner fifty eight finds it on. Not their signal, so they leave it.", "cap": "Day 3: #58 leaves it", "dur": 4.344, "extra": 0.5, "file": "vo/13.wav"}, {"text": "Day four, the counter finds it on, switches it off, and makes mark number one.", "cap": "Day 4: mark #1", "dur": 4.216, "extra": 0.6, "file": "vo/14.wav"}, {"text": "And if twenty three ever finds it off again? They leave it. They've already been counted.", "cap": "#23 never switches again", "dur": 4.311, "extra": 0.5, "file": "vo/15.wav"}, {"text": "Day after day, the marks pile up.", "cap": "Day after day...", "dur": 1.808, "extra": 3.2, "file": "vo/16.wav"}, {"text": "When the counter reaches ninety nine marks, plus themselves, that's all one hundred.", "cap": "99 marks + the counter = 100", "dur": 4.199, "extra": 0.6, "file": "vo/17.wav"}, {"text": "They tell the warden... and everyone walks free!", "cap": "Everyone walks free!", "dur": 2.348, "extra": 1.6, "file": "vo/18.wav"}, {"text": "The catch? On average, this takes about ten thousand days. That's twenty eight years!", "cap": "~10,400 days \u2248 28 years", "dur": 4.594, "extra": 0.8, "file": "vo/19.wav"}, {"text": "Could you wait that long? Follow for more puzzles!", "cap": "Follow for more puzzles", "dur": 2.58, "extra": 1.6, "file": "vo/20.wav"}];
